{
  "title": "User Support, Ticket Management, and Helpdesk Integration Cluster Documentation",
  "overview": "This cluster provides a comprehensive system for users to submit support tickets, facilitating both web-based and programmatic interactions. It integrates core components for ticket creation, validation, notification, and management, ensuring a robust and extensible support infrastructure. The system is designed to handle diverse support requests, including general inquiries and course-specific issues, and integrates with external systems for asynchronous processing.",
  "functional_domain": "User Support, Ticket Management, and Helpdesk Integration",
  "core_components": [
    {
      "name": "Helpdesk::Ticket Model",
      "description": "The central ActiveRecord model representing a support ticket. It includes fields for `title`, `report` (description), `topic` (e.g., technical, reactivation, course), `language`, `mail`, `url`, `data` (client information), and `user_id`. It belongs to an optional `Course::Course` model.",
      "details": {
        "source_file": "app/models/helpdesk/ticket.rb",
        "validations": [
          "Presence for `report`, `topic`, `language`, `title`.",
          "`title` max length 255, custom `allowed_title` to prevent URLs.",
          "`mail` validated for email format.",
          "`course_id` conditionally required if `topic` is 'course'."
        ],
        "associations": [
          "belongs_to :course, class_name: 'Course::Course', optional: true"
        ],
        "callbacks": [
          "after_commit on: :create: Sends email notification via `Helpdesk::TicketMailer`.",
          "after_commit on: :create: Publishes ticket JSON to RabbitMQ topic `xikolo.helpdesk.ticket.create` using `Msgr`.",
          "before_validation: Truncates `url` field if it exceeds 255 characters."
        ]
      }
    },
    {
      "name": "HelpdeskController",
      "description": "The frontend controller responsible for handling web-based ticket submissions. It orchestrates the user interaction, validation, and ticket creation process.",
      "details": {
        "source_file": "app/controllers/helpdesk_controller.rb",
        "integrations": [
          "`Xi::Recaptcha::Integration` for user submission verification."
        ],
        "methods": [
          "`create_ticket!`: Private method to construct `Helpdesk::Ticket` from request parameters, assigning `current_user`'s email/ID and deriving `topic`/`course_id` from a `category` parameter.",
          "`annotate_with_metadata`: Processes a `data` hash into a string for the ticket's `data` field.",
          "Referrer URL extraction: Attempts to get URL from `params[:url]` or `request.referer`, with graceful handling of invalid URIs.",
          "Layouts: Uses `helpdesk_layout` helper for 'simple' layout or no layout for XHR requests."
        ]
      }
    },
    {
      "name": "Helpdesk::TicketForm",
      "description": "A form object used by the `HelpdeskController` to encapsulate and manage ticket submission data. It defines the `data` attribute and provides dynamic category options.",
      "details": {
        "source_file": "app/forms/helpdesk/ticket_form.rb",
        "attributes": [
          "`data` attribute."
        ],
        "methods": [
          "`categories_for`: Suggests dynamic options for ticket categories based on the current user."
        ]
      }
    },
    {
      "name": "Helpdesk::TicketMailer",
      "description": "Responsible for sending email notifications upon the creation of a new helpdesk ticket. It ensures the relevant parties are informed.",
      "details": {
        "source_file": "app/mailers/helpdesk/ticket_mailer.rb",
        "configuration": "Sends emails to `Xikolo.config.helpdesk_email`.",
        "email_details": [
          "Sets `reply_to` address to the ticket submitter's email.",
          "Subject line prefixed with course information (channel code, course code) if ticket is course-related."
        ]
      }
    },
    {
      "name": "Xikolo::V2::Helpdesk::Tickets API Endpoint",
      "description": "A Grape-based API endpoint enabling programmatic creation of helpdesk tickets, allowing external systems or client applications to submit support requests.",
      "details": {
        "source_file": "api/xikolo/v2/helpdesk/tickets.rb",
        "writable_attributes": [
          "`title`, `report`, `topic`, `language`, `mail`, `url`, `data`."
        ],
        "mail_handling": "`mail` attribute automatically extracted from authenticated user if authorization header present, otherwise required for POST requests.",
        "course_relationship": "Supports associating a ticket with a `course` via `course_id` foreign key.",
        "post_action": "Creates a `Helpdesk::Ticket` record, automatically assigning `current_user`'s `id` and `email` if authenticated."
      }
    },
    {
      "name": "Xi::Recaptcha::Integration",
      "description": "A dedicated integration component for ReCAPTCHA services, used by the `HelpdeskController` to verify user submissions and prevent spam.",
      "details": {
        "source_file": "app/controllers/helpdesk_controller.rb (integrated)",
        "functionality": "Verifies user submissions, requiring manual verification if automated checks fail."
      }
    },
    {
      "name": "Msgr",
      "description": "A messaging library used for publishing messages to RabbitMQ, specifically for notifying other services about new helpdesk tickets.",
      "details": {
        "source_file": "app/models/helpdesk/ticket.rb (used in callback)",
        "functionality": "Publishes ticket JSON to the `xikolo.helpdesk.ticket.create` RabbitMQ topic."
      }
    },
    {
      "name": "Course::Course Model",
      "description": "An associated model representing a course, which can be optionally linked to a helpdesk ticket.",
      "details": {
        "source_file": "app/models/helpdesk/ticket.rb (associated)",
        "functionality": "Provides context for course-specific helpdesk tickets."
      }
    }
  ],
  "key_functionality": [
    "Web-based Ticket Submission: Users can submit support tickets through a dedicated web interface, leveraging form objects and ReCAPTCHA for validation.",
    "Programmatic API Ticket Submission: External systems or client applications can create tickets via a Grape-based RESTful API endpoint.",
    "Comprehensive Data Validation: Tickets undergo rigorous validation for presence, length, format (email, URL), and conditional requirements (e.g., `course_id` for 'course' topic).",
    "Automated Notification System: New ticket creation triggers email notifications to configured helpdesk addresses and publishes messages to a RabbitMQ topic for asynchronous processing.",
    "Security and Spam Prevention: Integration with `Xi::Recaptcha::Integration` helps verify user submissions and mitigate spam on the web interface.",
    "Contextual Ticket Creation: Automatically assigns authenticated user information (ID, email) and derives topic/course context based on submission parameters and referrer URLs.",
    "Extensible Data Capture: A generic `data` field allows for capturing additional, unstructured client information.",
    "Helpdesk Administration: Permissions exist for managing helpdesk-related content such as pages and polls, indicating broader administrative capabilities beyond just ticket submission."
  ],
  "workflows": [
    {
      "name": "User Submits Helpdesk Ticket (Frontend)",
      "description": "A user navigates to the helpdesk page, fills out a form, and submits it. The `HelpdeskController` validates the submission (including ReCAPTCHA via `Xi::Recaptcha::Integration`), processes the data using `Helpdesk::TicketForm`, and creates a `Helpdesk::Ticket` record. Upon successful creation, a success message is rendered, an email is sent via `Helpdesk::TicketMailer`, and a message is published to RabbitMQ via `Msgr`.",
      "components_involved": [
        "HelpdeskController",
        "Helpdesk::TicketForm",
        "Helpdesk::Ticket",
        "Helpdesk::TicketMailer",
        "Xi::Recaptcha::Integration",
        "Msgr"
      ]
    },
    {
      "name": "User Submits Helpdesk Ticket (API)",
      "description": "An external system or client application sends a POST request to the `/api/v2/helpdesk/tickets` endpoint. The `Xikolo::V2::Helpdesk::Tickets` API endpoint receives the request, validates the provided attributes, potentially enriches it with authenticated user information, and creates a `Helpdesk::Ticket` record. This action triggers email notifications via `Helpdesk::TicketMailer` and RabbitMQ messages via `Msgr`, similar to the frontend workflow.",
      "components_involved": [
        "Xikolo::V2::Helpdesk::Tickets API Endpoint",
        "Helpdesk::Ticket",
        "Helpdesk::TicketMailer",
        "Msgr"
      ]
    },
    {
      "name": "Helpdesk Ticket Processing",
      "description": "Once a `Helpdesk::Ticket` is successfully created (either via frontend or API), an email notification is sent to the configured helpdesk email address using `Helpdesk::TicketMailer`. Concurrently, a message containing the ticket's JSON representation is published to the `xikolo.helpdesk.ticket.create` RabbitMQ topic using `Msgr`. This enables asynchronous processing by other services or external helpdesk systems that consume these messages.",
      "components_involved": [
        "Helpdesk::Ticket",
        "Helpdesk::TicketMailer",
        "Msgr"
      ]
    }
  ],
  "permissions_and_roles": {
    "description": "The `account` microservice defines specific roles for helpdesk administration, indicating broader management capabilities beyond just ticket submission.",
    "roles": [
      "`helpdesk.pages.admin`: For storing helpdesk pages.",
      "`helpdesk.polls.admin`: For managing helpdesk polls."
    ],
    "assignment": "These roles are granted to the `xikolo.admins` group within the `root` context."
  },
  "technical_considerations_and_debt": [
    {
      "issue": "Direct `params` access in `HelpdeskController`",
      "description": "The `HelpdeskController`'s `create_ticket!` method directly accesses `params` multiple times without consistently using `ticket_params` for all values. While `params.permit` is used for `ticket_params`, this pattern could introduce mass assignment vulnerabilities if not meticulously managed across all parameter usages.",
      "source": "app/controllers/helpdesk_controller.rb"
    },
    {
      "issue": "Generic `data` field",
      "description": "The `data` field in `Helpdesk::Ticket` and `Helpdesk::TicketForm` is a generic string. This approach might lead to inconsistent data storage if various client information needs to be captured. A more structured approach, such as using a JSONB column, would be beneficial for improved querying, analysis, and data integrity.",
      "source": "app/models/helpdesk/ticket.rb, app/forms/helpdesk/ticket_form.rb"
    },
    {
      "issue": "`allowed_title` validation complexity",
      "description": "The `allowed_title` validation uses `URI::DEFAULT_PARSER.make_regexp` to prevent URLs in the title. This regular expression can be complex and potentially lead to unexpected behavior, false positives, or false negatives depending on the exact definition of what constitutes a 'URL' within a title.",
      "source": "app/models/helpdesk/ticket.rb"
    }
  ]
}

